// @ts-check
// tarn · icons: Lucide (ISC), pinned version, only used symbols (icons/, js/icons-data.js – generated by
// tools/icons.mjs, sources and license in icons/SOURCES.md). 24×24 symbols, stroke in currentColor; icon() draws them with
// an absolute 1.5 px stroke, independent of size. New symbols: node tools/icons.mjs add <lucide-name> [--as <name>].
import { s } from './dom.js';
import { ICONS } from './icons-data.js';

export const ICON_NAMES = Object.keys(ICONS);

/** Shapes of a symbol [[tag, { attr }], …] (24×24) for drawings outside the DOM, e.g. favicon(); otherwise null. */
export const iconParts = (name) => ICONS[name] || null;

/**
 * @param {string} name
 * @param {{ size?: number, label?: string }} [o] label makes the icon meaningful (role img); without it the icon is decorative
 * @returns {SVGElement}
 */
export function icon(name, { size = 16, label } = {}) {
  const svg = s('svg', {
    class: 'tn-icon', width: size, height: size, viewBox: '0 0 24 24', fill: 'none',
    stroke: 'currentColor', 'stroke-width': +(36 / size).toFixed(3), 'stroke-linecap': 'round', 'stroke-linejoin': 'round', // 1.5 px absolute
    'aria-hidden': label ? null : 'true', role: label ? 'img' : null, 'aria-label': label || null, focusable: 'false',
  });
  for (const [tag, attrs] of ICONS[name] || []) svg.append(s(tag, attrs));
  return svg;
}
